+                        failedPermitAcquisitions.add(label);
+                    }
+                } catch (InterruptedException e) {
+                    logger.warn("--> interrupted while acquiring permit [{}]", label);
+                    Thread.currentThread().interrupt();
+                    logAndFailTest(e);
+                }
+            });
+        }
