+        private void enqueueAction(final CheckedRunnable<Exception> action) {
+            if (shouldStop.get()) {
+                return;
+            }
+
+            threadPool.scheduleUnlessShuttingDown(TimeValue.timeValueMillis(between(1, 500)), CLIENT, mustSucceed(action));
+        }
