+                        if (cloneableIndices.isEmpty()) {
+                            getIndicesStep.onResponse(Collections.emptyList());
+                            return;
+                        }
+
+                        if (failedShardIndices.isEmpty() && randomBoolean()) {
+                            getIndicesStep.onResponse(Collections.singletonList("*"));
+                            return;
