+                    if (snapshotSpecificIndices) {
+                        createSnapshotRequestBuilder.setIndices(targetIndexNames.toArray(new String[0]));
+                    }
+
+                    final boolean abortSnapshot = randomBoolean();
+                    final Runnable abortRunnable;
+                    if (abortSnapshot) {
