-
-            if (bucket.getZone() != DateTimeZone.UTC) {
-                String format = hasMilliSecondPrecision ? "epoch_millis" : "epoch_second";
-                throw new IllegalArgumentException("time_zone must be UTC for format [" + format + "]");
-            } else if (isPositive && isTooLong) {
-                return -1;
