+    private static class ShardRequest {
+        final int round;
+        final DiscoveryNode node;
+        final FieldCapabilitiesIndexRequest request;
+
+        ShardRequest(int round, DiscoveryNode node, FieldCapabilitiesIndexRequest request) {
+            this.round = round;
+            this.node = node;
+            this.request = request;
+        }
+    }
