+
+    static Version randomOldVersion() {
+        final Version previousVersion = VersionUtils.getPreviousVersion(GROUP_REQUESTS_VERSION);
+        return VersionUtils.randomVersionBetween(random(), Version.V_7_0_0, previousVersion);
+    }
