+public class RestModifyDataStreamsAction extends BaseRestHandler {
+
+    @Override
+    public String getName() {
+        return "modify_data_stream_action";
+    }
+
+    @Override
+    public List<Route> routes() {
+        return List.of(new Route(POST, "/_data_stream/_modify"));
