+                            ((AbstractRunnable) runnable).onRejection( new EsRejectedExecutionException(msg, true));
+                        }
+                    }
+                }
+            }
+        } catch (InterruptedException e) {
+            Thread.currentThread().interrupt();
+        } finally {
+            awaitTermination.countDown();
+        }
+    }
