+                listener.onFailure(e);
+            }
+        });
+        logger.debug("submitted update task to clear migration results");
+    }
+
+    private SystemIndexMigrationInfo currentMigrationInfo() {
+        synchronized (migrationQueue) {
+            return migrationQueue.peek();
+        }
+    }
